import { describe, test, expect } from 'bun:test';
import { sha224 } from './sha224.js';
import { sha256 } from './sha256.js';
import { bitArray } from '../utils/bitArray.js';
import { utf8 } from '../../io/codec/utf8.js';
import { hex } from '../../io/codec/hex.js';

const _ba = bitArray.factory();
const _utf8 = utf8.factory();
const _hex = hex.factory();
const _sha256 = sha256.factory(_ba, _utf8);
const _sha = sha224.factory(_sha256);

const toHex = (ba) => _hex.fromBytes(_ba.ba_to_ui8(ba));

// Build a bitArray of exactly `bitLen` bits from a hex string holding
// ceil(bitLen/8) bytes (excess trailing bits in the last byte are discarded).
const haxToBitsBA = (hexStr, bitLen) => {
    if (bitLen === 0) return [];
    const bytes = _hex.toBytes(hexStr);
    const ba = _ba.ui8_to_ba(bytes);
    return _ba.clamp(ba, bitLen);
};

describe('sha224 module', () => {

    test('module metadata', () => {
        expect(sha224.name).toBe('sha224');
        expect(sha224.dependencies).toEqual(['sha256']);
    });

    describe('FIPS-180 vectors', () => {
        test('empty string', () => {
            expect(toHex(_sha.hash('')))
                .toBe('d14a028c2a3a2bc9476102bb288234c415a2b01f828ea62ac5b3e42f');
        });

        test('"abc"', () => {
            expect(toHex(_sha.hash('abc')))
                .toBe('23097d223405d8228642a477bda255b32aadbce4bda0b3f7e36c9da7');
        });

        test('448-bit message', () => {
            const msg = 'abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq';
            expect(toHex(_sha.hash(msg)))
                .toBe('75388b16512776cc5dba5da1fd890150b0c6455cb4f58b1952522525');
        });
    });

    describe('streaming', () => {
        test('chunked update matches one-shot', () => {
            const oneShot = toHex(_sha.hash('the quick brown fox jumps over the lazy dog'));
            const h = new _sha.fn();
            h.update('the quick brown ');
            h.update('fox jumps ');
            h.update('over the lazy dog');
            expect(toHex(h.finalize())).toBe(oneShot);
        });

        test('digest is 224 bits (7 x 32-bit words)', () => {
            const out = _sha.hash('hello');
            expect(out.length).toBe(7);
        });
    });
});

